import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import cn from 'classnames';

import { EMainRoutes } from 'shared/typings';
import { Content, Link } from 'shared/ui';

import styles from './Dashboard.module.scss';

interface IDashboardProps extends HTMLAttributes<HTMLDivElement> {}

export const Dashboard: FC<IDashboardProps> = ({ className, ...props }) => {
	const { t } = useTranslation();

	return (
		<Content {...props} className={cn(className, styles.dashboard)}>
			<Link to={EMainRoutes.CHANNELS}>{t('Каналы и группы')}</Link>
		</Content>
	);
};

export default Dashboard;
